```
const BREAKS = ['\n', '\x85', '\u2028', '\u2029'];
function analyzeScalar(scalar) {
  if (scalar === '') return {empty:true, multiline:false, allowBlock:false};
  let lineBreaks=false, special=false;
  let leadingSpace=false, leadingBreak=false, trailingSpace=false, trailingBreak=false;
  let breakSpace=false, spaceBreak=false;
  // iterate code points
  const cps = Array.from(scalar); // code points
  let prev = null;
  for (let i=0;i<cps.length;i++){
    const ch = cps[i]; const cp = ch.codePointAt(0);
    if (BREAKS.includes(ch)) lineBreaks = true;
    if (!(ch === '\n' || (cp >= 0x20 && cp <= 0x7E))) {
      // unicode printable check
      const isUnicodePrintable = (cp === 0x85 || (cp>=0xA0 && cp<=0xD7FF) || (cp>=0xE000 && cp<=0xFFFD) || (cp>=0x10000 && cp<0x10FFFF)) && cp !== 0xFEFF;
      // with allow_unicode False both branches → special
      special = true;
    }
    if (ch === ' ') {
      if (i===0) leadingSpace=true;
      if (i===cps.length-1) trailingSpace=true;
      if (prev !== null && BREAKS.includes(prev)) breakSpace=true;
    }
    if (BREAKS.includes(ch)) {
      if (i===0) leadingBreak=true;
      if (i===cps.length-1) trailingBreak=true;
      if (prev === ' ') spaceBreak=true;
    }
    prev = ch;
  }
  let allowBlock = true;
  if (trailingSpace) allowBlock=false;
  if (spaceBreak || special) allowBlock=false;
  return {empty:false, multiline:lineBreaks, allowBlock};
}
```
